  y=z["future_labels"];pr=np.stack([z["future_keep"],z["future_reset"],z["future_commit"]],axis=1);assert pr.shape==(len(x),3,4,5) and np.isfinite(pr).all() and abs(pr.sum(-1)-1).max()<1e-5;labels=np.broadcast_to(y[:,None,:,None],(len(y),3,4,1));ce=-np.log(np.clip(np.take_along_axis(pr,labels,axis=3)[...,0],1e-12,1));gain=(ce[:,0:1]-ce).mean(2);balanced=((ce[:,0:1]-ce)*cw[y][:,None]).mean(2);correct=(pr.argmax(-1)==y[:,None]);correct_gain=(correct.astype(float)-correct[:,0:1]).mean(2)*100;err=float(abs(gain[:,1:]-z["future_gain"]).max());maxce=max(maxce,err);assert err<3e-6
