  part=dict(features=x,future_gain=z["future_gain"],current_gain=z["current_gain"],subject=np.full(len(x),sid),trajectory=np.full(len(x),trajectory),gain=gain,balanced=balanced,correct_gain=correct_gain,t=times);parts.append(part);audits.append(dict(subject=sid,trajectory=trajectory,pulses=len(x),future_ce_recompute_error=err,source_scope_training_disjoint=True))
  for name,index in [("WRITE",2),("RESET",1)]:
   mechanism.append(dict(subject=sid,trajectory=trajectory,action=name,utility=float(gain[:,index].mean()),balanced_utility=float(balanced[:,index].mean()),accuracy_gain_pp=float(correct_gain[:,index].mean()),positive_pulse_fraction=float((gain[:,index]>1e-6).mean()),negative_pulse_fraction=float((gain[:,index]<-1e-6).mean()),oracle_write_utility=float(np.maximum(gain[:,2],0).mean()),oracle_all_utility=float(gain.max(1).mean())))
